import pyAether as pyScript

def use_emypointarrayf(int_points):
    ia = pyScript.emyPointArray(len(int_points))
    for pt in int_points:
        ia.append(pt)
    fa = pyScript.emyPointArrayF(ia)
    return fa.toList()

import pyAether as pyScript

def use_emybox(left, bottom, right, top):
    box = pyScript.emyBox(left, bottom, right, top)
    if box.hasNoArea():
        raise RuntimeError("emyBox has no area")
    return box

