import pyAether as pyScript

def vary_emypointarray(groups):
    out = []
    for pts in groups:
        arr = pyScript.emyPointArray(len(pts))
        for x, y in pts:
            arr.append(pyScript.emyPoint(x, y))
        arr.compress(False)
        out.append(arr.getNumElements())
    return out

import pyAether as pyScript

def point_to_box_bbox(x1, y1, x2, y2):
    ll = pyScript.emyPoint(x1, y1)
    rt = pyScript.emyPoint(x2, y2)
    box = pyScript.emyBox(ll, rt)
    return box.getWidth(), box.getHeight()

