def scale_points(corners, fx, fy):
    ia = pyScript.emyPointArray(len(corners))
    for c in corners:
        ia.append(pyScript.emyPoint(c[0], c[1]))
    fa = pyScript.emyPointArrayF(ia)
    fa.magnifyIn2D(fx, fy)
    return fa.toList()

import pyAether as pyScript

def build_selection_mask(length, enabled):
    ba = pyScript.emyBitArray(length)
    ba.clear()
    for i in enabled:
        ba.set(i)
    return ba, ba.countPiece()
